<div class="topline"><span><?= e(t('BUILD WHAT COMES NEXT')) ?></span><span><?= e(t('Skills. Learning. Opportunities.')) ?></span></div><header class="page-header"><div><h1><?= e(t('Make room for your future.')) ?></h1><p class="muted"><?= e(t('Track the skills you’re growing and the opportunities you’re pursuing.')) ?></p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<nav class="tabs" aria-label="<?= e(t('Career pages')) ?>"><?php foreach (['skills'=>t('Skills'),'courses'=>t('Courses'),'applications'=>t('Applications & interviews')] as $key=>$label): ?><a href="/career?view=<?= e($key) ?>" <?= $tab===$key ? 'class="selected" aria-current="page"' : '' ?>><?= e($label) ?></a><?php endforeach; ?></nav>
<div class="stats"><section class="card"><p class="muted"><?= e(t('Skills tracked')) ?></p><div class="big-number"><?= count($skills) ?></div></section><section class="card"><p class="muted"><?= e(t('Courses completed')) ?></p><div class="big-number"><?= count(array_filter($courses,fn($c)=>$c['status']==='completed')) ?></div></section><section class="card"><p class="muted"><?= e(t('Active applications')) ?></p><div class="big-number"><?= count(array_filter($applications,fn($a)=>!in_array($a['status'],['accepted','rejected','withdrawn'],true))) ?></div></section></div>
<div class="two-col"><section class="card"><h2><?= e(match($tab) {'skills'=>t('Your skills'),'courses'=>t('Your learning'),default=>t('Your opportunities')}) ?></h2>
<?php if ($tab==='skills'): if (!$skills): ?><p class="muted"><?= e(t('No data yet. Add a skill you want to strengthen.')) ?></p><?php else: foreach ($skills as $skill): ?><article class="lesson-entry"><div class="section-heading"><strong><?= e($skill['name']) ?></strong></div><?= progress_donut((float)$skill['progress'],'Skill progress','Your self-assessed progress',true,'violet','Progress') ?><small><?= $skill['target_date'] ? t('Target ').e($skill['target_date']) : t('No target date') ?></small><p class="muted"><?= e($skill['notes']) ?></p><details><summary><?= e(t('Edit skill')) ?></summary><?php $record=$skill; $formType='skills'; require __DIR__.'/record-form.php'; unset($record); ?></details><form method="post" action="/career/skills/<?= e($skill['id']) ?>/delete" data-confirm="Delete this skill? Linked courses will keep their history without the skill link."><?= csrf_field() ?><button class="delete"><?= e(t('Delete skill')) ?></button></form></article><?php endforeach; endif; ?>
<?php elseif ($tab==='courses'): if (!$courses): ?><p class="muted"><?= e(t('No data yet. Record a course you want to take.')) ?></p><?php else: foreach ($courses as $course): ?><article class="lesson-entry"><div class="section-heading"><strong><?= e($course['name']) ?></strong><span class="badge"><?= e(CareerService::COURSE_STATUSES[$course['status']]) ?></span></div><small><?= e($course['provider']) ?><?= $course['skill'] ? ' · '.e($course['skill']) : '' ?><?= $course['due_date'] ? ' · Due '.e($course['due_date']) : '' ?></small><?= progress_donut((float)$course['progress'],'Course completion','Your recorded course progress',true,'green') ?><?php if ($course['resource']): ?><p class="footnote"><?= e(t('Reference:')) ?> <?= e($course['resource']) ?></p><?php endif; ?><p class="muted"><?= e($course['notes']) ?></p><details><summary><?= e(t('Edit course')) ?></summary><?php $record=$course; $formType='courses'; require __DIR__.'/record-form.php'; unset($record); ?></details><form method="post" action="/career/courses/<?= e($course['id']) ?>/delete" data-confirm="Delete this course?"><?= csrf_field() ?><button class="delete"><?= e(t('Delete course')) ?></button></form></article><?php endforeach; endif; ?>
<?php else: if (!$applications): ?><p class="muted"><?= e(t('No data yet. Save your first role or application.')) ?></p><?php else: foreach ($applications as $application): ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($application['role']) ?></strong><small><?= e($application['organization']) ?></small></div><span class="badge"><?= e(CareerService::APPLICATION_STATUSES[$application['status']]) ?></span></div><dl class="lesson-detail"><dt><?= e(t('Applied')) ?></dt><dd><?= e($application['applied_date'] ?? t('Not recorded')) ?></dd><dt><?= e(t('Deadline')) ?></dt><dd><?= e($application['deadline'] ?? t('Not recorded')) ?></dd><dt><?= e(t('Interview')) ?></dt><dd><?= e($application['interview_at'] ?? t('Not scheduled')) ?></dd><dt><?= e(t('Reference')) ?></dt><dd><?= e($application['resource'] ?: t('Not recorded')) ?></dd></dl><p class="muted"><?= e($application['notes']) ?></p><details><summary><?= e(t('Edit application')) ?></summary><?php $record=$application; $formType='applications'; require __DIR__.'/record-form.php'; unset($record); ?></details><form method="post" action="/career/applications/<?= e($application['id']) ?>/delete" data-confirm="Delete this application?"><?= csrf_field() ?><button class="delete"><?= e(t('Delete application')) ?></button></form></article><?php endforeach; endif; endif; ?>
</section><section class="card"><h2><?= e(match($tab) {'skills'=>t('Add a skill'),'courses'=>t('Add a course'),default=>t('Add an application')}) ?></h2><?php $formType=$tab; require __DIR__.'/record-form.php'; ?></section></div>
